+  if (spindleOn) { block(["M5"]); spindleOn = false; }
+  safeRetractBlock();
+  var eu = optStr("EndUnits", "").toLowerCase();
+  if (eu === "inch" && !unitInch) block(["G20"]);
+  else if (eu === "mm" && unitInch) block(["G21"]);
+  block(["M30"]);
+  writeln("%");
+}

