+    assert!(post_serves("Hurco WinMax (NC)", Kind::Mill));
+    assert!(post_serves("Hurco WinMax (NC)", Kind::MillTurn));
+    assert!(!post_serves("Hurco WinMax (NC)", Kind::Lathe));
